import { PythonRuntime } from '../compiler/runtime';
import { toInt } from '../audio/utils';
import { TunePadCell } from './cell';


/**
 * ## TunePadCanvas cell (an object that other tunepad python cells can draw on)
 * ```html
 * <tunepad-canvas
 *    uuid = "{{ database UUID }}"
 *    name = "{{ valid python file }}"
 *    width = "{{ pixel width }}"
 *    height = "{{ pixel height }}">
 * </tunepad-canvas>
 * ```
 */
export class TunePadCanvas extends HTMLElement {

    static readonly ELEMENT = "tunepad-canvas";

    static observedAttributes = [
        "uuid",
        "name",
        "width",
        "height"
    ];

    /** unique database identifier */
    uuid : string = self.crypto.randomUUID();

    /** canvas "name". should be a legal and unique python identifier */
    name : string = 'tunepad_canvas';

    /** inner canvas object */
    canvas : HTMLCanvasElement;

    /** all of the HTML elements are contained within a shadow DOM */
    private root : ShadowRoot;



    constructor() {
        super();
        this.root = this.attachShadow({ mode: 'open' });
        this.canvas = document.createElement('canvas');
        this.canvas.setAttribute('part', 'canvas');
        this.canvas.setAttribute('style', 'width: 100%;');

        // singleton object and it's safe to call init() multiple times
        PythonRuntime.init();
    }


    async connectedCallback() {
        this.root.append(this.canvas);
        PythonRuntime.registerCanvas(this.name, this.canvas);

        // register pointer events for the canvas
        [
            'click',
            'pointerdown',
            'pointerup',
            'pointermove',
            'pointerenter',
            'pointerleave'
        ]
        .forEach(event => {
            this.canvas.addEventListener(event, e => {
                document.querySelectorAll(`tunepad-cell[canvas="${this.name}"]`).forEach(cell => {
                    const rect = this.canvas.getBoundingClientRect();
                    const tpc = cell as TunePadCell;
                    const sx = (this.canvas.width / rect.width);
                    const sy = (this.canvas.height / rect.height);
                    const x = (e as PointerEvent).offsetX * sx;
                    const y = (e as PointerEvent).offsetY * sy;
                    tpc.pythonEvent(event, [ x, y ]);
                    if (event === 'pointermove' && (e as PointerEvent).buttons > 0) {
                        tpc.pythonEvent('pointerdrag', [ x, y ]);
                    }
                });
            });
        });
    }


    disconnectedCallback() {
        PythonRuntime.unregisterCanvas(this.name);
    }


    attributeChangedCallback(name : string, oldValue : string, newValue : string) {
        if (name === 'uuid') {
            this.uuid = newValue;
        }
        else if (name === 'name') {
            this.setName(newValue);
        }
        else if (name === 'width') {
            this.canvas.width = toInt(newValue, 500);
        }
        else if (name === 'height') {
            this.canvas.height = toInt(newValue, 500);
        }
    }


    /**
     * setName can be called from the outline class to change the name of a cell
     * to a valid python identifier.
     */
    public setName(name : string) {
        if (name === this.name) return;
        // FIXME: Causes error
        //PythonRuntime.unregisterCanvas(this.name);
        this.name = PythonRuntime.makePythonSafe(name, this.uuid);
        this.setAttribute('name', this.name);
        // FIXME: PythonRuntime.registerCanvas(this.name, this.canvas);
    }
}
