import html from './bpm-dialog.module.html';
import { toInt } from '../../audio';

/**
 * Tempo Dialog (extends HTMLDialogElement)
 * ```html
 * <dialog is="bpm-dialog" tempo="90"></dialog>
 * ```
 */

export class BPMDialog extends HTMLDialogElement {

    static readonly ELEMENT = "bpm-dialog";

    static observedAttributes = [ "tempo" ];

    private bpm = 90;


    static show(tempo : number) : HTMLDialogElement {
        const dialog = document.createElement('dialog', { is: BPMDialog.ELEMENT}) as HTMLDialogElement;
        dialog.setAttribute('tempo', `${tempo}`);
        dialog.classList.add('bpm-dialog');
        document.body.append(dialog);
        dialog.showModal();
        dialog.addEventListener('click', (event) => {
            const r = dialog.getBoundingClientRect();
            const cx = event.clientX;
            const cy = event.clientY;
            if (cy < r.top || cy > r.bottom || cx < r.left || cx > r.right) {
                dialog.close();
                dialog.remove();
            }
        });
        return dialog;
    }


    constructor() {
        super();
        this.innerHTML = html;
    }

    connectedCallback() {
        const bpmField = this.querySelector('.tempo') as HTMLInputElement;
        bpmField.addEventListener('keypress', e => {
            if (e.key === "Enter") {
                bpmField.blur();
                this.close();
                this.remove();
            }
        });
        bpmField.addEventListener('input', e => {
            bpmField.value = bpmField.value.replaceAll(/[^0-9]/g, '');
        });
        bpmField.addEventListener('blur', e => {
            this.setTempo(toInt(bpmField.value, 100));
            this.emitUpdateEvent('tempo', this.bpm);
        })

        this.bindSpinnerButton(
            '.tempo-up', 
            () => { this.adjustTempo(1) },
            () => { this.emitUpdateEvent('tempo', this.bpm) }
        );
        this.bindSpinnerButton(
            '.tempo-down',
            () => { this.adjustTempo(-1) },
            () => { this.emitUpdateEvent('tempo', this.bpm) }
        );
    }

    disconnectedCallback() { }

    /**
     * When an attribute is changed on our custom component, this gets fired...
     */
    attributeChangedCallback(name : string, oldValue : string, newValue : string) {
        if (name === 'tempo') {
            this.setTempo(toInt(newValue, this.bpm));
        }
    }

    private setTempo(newBPM : number) {
        this.bpm = Math.max(5, Math.min(999, newBPM));
        const bpmField = this.querySelector('.tempo');
        if (bpmField) (bpmField as HTMLInputElement).value = `${this.bpm}`;
     }

    private adjustTempo(delta : number) {
        this.setTempo(this.bpm + delta);
    }
    
    /**
     * SPINNER +/- BUTTONS
     * events for the tempo buttons. we implement press and hold
     * to rapidly increase the tempo by holding the button down.
     */
    private bindSpinnerButton(selector : string, spinAction : () => void, releaseAction : () => void) {
        const button = this.querySelector(selector);
        let down = false;
        let hold : number | undefined = undefined;
        let release : number | undefined = undefined;
        let trigger : number | undefined = undefined;
        button?.addEventListener('pointerup', e => {
            clearInterval(hold);
            clearTimeout(release);
            clearTimeout(trigger);
            down = false;
            release = setTimeout(releaseAction, 1500);
        });
        button?.addEventListener('pointerdown', e => {
            clearInterval(hold);
            clearTimeout(release);
            spinAction();
            down = true;
            trigger = setTimeout(() => {
                hold = setInterval(() => { down ? spinAction() : clearInterval(hold) }, 50);
            }, 700);
        });
        button?.addEventListener('click', e => { e.stopImmediatePropagation() });
    }


    /**
     * Fire custom events whenever the value is changed by the user
     */
    private emitUpdateEvent(name : string, value : number) {
        this.dispatchEvent(
            new CustomEvent(name, {
                bubbles: true,
                composed: true,
                detail: { value }
            })
        );
    }
}
