import { MusicKey, TunePadAudio, toInt } from '../audio';
import { TunePadCell } from './cell';
import { TunePadFile } from './file';
import { PythonRuntime } from '../compiler/runtime';
import { ProjectPersistence } from './persistence';

/**
 * ## TunePad project
 * ```html
 * <tunepad-project
 *    uuid = "{{ database UUID }}"
 *    name = "{{ python module name }}"  // must be a valid python identifier
 *    readonly = "false"                 // default is false
 *    tempo = "90"
 *    key = "C Major"
 *    persistence = "wss://d65.tunepad.space/websocket/"
 *    awareness = "{username}:{user-color}" or "{username}"
 *    time = "4/4">
 * 
 *    <!-- optional -->
 *    <tunepad-project-menu>
 * 
 *    <!-- optional -->
 *    <tunepad-block-menu> ... </tunepad-block-menu>
 * 
 *    <!-- required -->
 *    <tunepad-cell-list>
 *        <tunepad-cell></tunepad-cell>
 *        <tunepad-cell></tunepad-cell>
 *        <p> Other html content </p>
 *        <tunepad-cell></tunepad-cell>
 * 
 *        <!-- etc -->
 *    </tunepad-cell-list>
 * 
 *    <!-- optional -->
 *    <tunepad-outline></tunepad-outline>
 * </tunepad-project>
 * ```
 */
export class TunePadProject extends HTMLElement {

    static readonly ELEMENT = "tunepad-project";

    static observedAttributes = [
        "uuid",        // database ID (should never change)
        "name",        // name of this project
        "readonly",    // boolean string, default is false
        "tempo",
        "key",
        "share",       // "private", "viewonly", "collaborative"
        "time",        // time signature (e.g. "4/4")
        "voices",      // path to patch list for synth (e.g. /assets/sounds/voices)
        "persistence", // Y.js websocket persistence provider (e.g. "ws://localhost:3003")
        "awareness"    // Y.js awareness "{username}:{user-color}" or "{username}"
    ];

    /** unique database identifier */
    uuid : string = self.crypto.randomUUID();

    /** project name */
    name : string = 'tunepad_project';

    /** TunePad audio system */
    private audio : TunePadAudio;

    /** allows project to keep track of added and deleted tunepad-cells */
    private observer? : MutationObserver;

    constructor() {
        super();
        this.audio = TunePadAudio.init();
        this.audio.addSubscriber(this);
    }

    onClockReset() { }

    onClockTimeChange() { }

    onTempoChange() {
        this.setAttribute('tempo', `${this.audio.bpm}`);
    }

    onKeyChange() {
        this.setAttribute('key', this.audio.key.name);
    }

    onTimeSignatureChange() { 
        this.setAttribute('time', `${this.audio.beatsPerMeasure}/${this.audio.beatValue}`);
    }

    async connectedCallback() {

        /**
         * Generate custom events for cells added, removed, or updated
         */
        this.observer = new MutationObserver(mutations => {
            for (const mutation of mutations) {
                for (const node of mutation.addedNodes) {
                    if (node.nodeName.toLowerCase() === 'tunepad-cell') {
                        const cell = node as TunePadCell;
                        this.dispatchEvent(new CustomEvent('cell-added', { 
                            bubbles: false, composed: true, detail : { uuid : cell.uuid }
                        }));
                        cell.addEventListener('update-cell', cellUpdateEvent);
                        cell.addEventListener('delete-cell', cellUpdateEvent);
                        cell.addEventListener('copy-cell', cellUpdateEvent);
                        cell.addEventListener('compiled', cellUpdateEvent);
                    }
                }
                for (const node of mutation.removedNodes) {
                    if (node.nodeName.toLowerCase() === 'tunepad-cell') {
                        const cell = node as TunePadCell;
                        this.dispatchEvent(new CustomEvent('cell-removed', {
                            bubbles: false, composed: true, detail : { uuid : cell.uuid }
                        }));
                        cell.removeEventListener('update-cell', cellUpdateEvent);
                        cell.removeEventListener('delete-cell', cellUpdateEvent);
                        cell.removeEventListener('copy-cell', cellUpdateEvent);
                        cell.removeEventListener('compiled', cellUpdateEvent);
                    }
                }
                /*
                if (mutation.type === 'attributes' && mutation.target.nodeName.toLowerCase() === 'tunepad-cell') {
                    const cell = mutation.target as TunePadCell;
                    const attrib = `${mutation.attributeName}`; 
                    const newValue = cell.getAttribute(attrib);
                    if (newValue !== mutation.oldValue && attrib !== 'class') {
                        this.emitCellEvent(cell.getAttribute('uuid'), attrib, newValue);
                    }
                }
                if (mutation.type === 'attributes' && mutation.target === this) {
                    const attrib = `${mutation.attributeName}`;
                    const newValue = this.getAttribute(attrib);
                    if (newValue !== mutation.oldValue) { ; }
                }
                */
            }
        });
        //this.observer?.observe(this, { subtree: true, childList: true, attributes: true, attributeOldValue: true });
        this.observer?.observe(this, { subtree: true, childList: true });


        await this.waitForWindowLoad();

        // start yjs persistence?
        if (this.hasAttribute('persistence')) {
            ProjectPersistence.Initialize(this);
        }

        this.querySelector('tunepad-project-menu')?.addEventListener('update', e => {
            const { property, value } = (e as CustomEvent).detail;
            if (property === 'key') {
                this.setAttribute('key', value);
            } 
            else if (property === 'tempo') {
                this.setAttribute('tempo', value);
            }
            else if (property === 'time') {
                this.setAttribute('time', value);
            }
            else if (property === 'name') {
                this.setAttribute('name', value);
            }
        });

        this.querySelector('tunepad-project-menu')?.addEventListener('action', e => {
            const { action } = (e as CustomEvent).detail;
            if (action === 'play') {
                this.querySelectorAll('tunepad-cell').forEach((cell) => {(cell as TunePadCell).playAudio() });
            }
            else if (action === 'pause') {
                this.querySelectorAll('tunepad-cell').forEach((cell) => {(cell as TunePadCell).pauseAudio() });
            }
            else if (action === 'stop') {
                this.audio.stopAll();
            }
            else {
                this.relayEvent(e as CustomEvent);
            }
        });

        this.querySelector('tunepad-outline')?.addEventListener('add-cell', e => {
            this.dispatchEvent(new CustomEvent("add-cell", {
                bubbles: false,
                composed: true,
                detail: { uuid : this.uuid }
            }));
        });

        this.querySelector('tunepad-outline')?.addEventListener('reorder-cells', e => {
            this.relayEvent(e as CustomEvent);
        });


        const proj = this;
        function cellUpdateEvent(evt : Event) {
            proj.dispatchEvent(new CustomEvent(evt.type, {
                bubbles: false, composed: true, detail: (evt as CustomEvent).detail
            }));
        }
    }

    disconnectedCallback() {
        this.observer?.disconnect();
    }

    attributeChangedCallback(name : string, oldValue : string | null, newValue : string | null) {
        if (newValue === oldValue) {
            return;
        }
        else if (name === 'uuid' && newValue) {
            this.uuid = newValue;
        }
        else if (name === 'name' && newValue !== this.name && newValue) {
            this.name = newValue;
            this.querySelector('tunepad-project-menu')?.setAttribute('name', newValue);
        }
        else if (name === 'tempo') {
            this.audio.bpm = toInt(newValue, 90);
        }
        else if (name === 'key' && newValue) {
            this.audio.key = new MusicKey(newValue);
        }
        else if (name === 'time' || name == 'time-signature') {
            this.audio.setTimeSignature(newValue!);
        }
        else if (name === 'voices' && newValue) {
            this.audio.voices = newValue;
        }
        else if (name === 'readonly') {
            this.setReadOnly(newValue === 'true');
        }
        else if (name === 'persistence' && oldValue === null) {
            ProjectPersistence.Initialize(this);
        }
        this.emitUpdateEvent(name, newValue);
    }


    /**
     * Serialize this project and all cells. Return a JSON stringified object
     */
    public save() : any {
        const data : any = { };
        this.getAttributeNames().forEach(attrib => {
            if (attrib !== 'persistence' && attrib !== 'awareness') {
                data[attrib] = this.getAttribute(attrib)
            }
        });
        data.files = [];
        data.cells = [];

        // FIXME: Temporarily disabling file saving because it wastes a ton of space in the database
        const files = document.querySelectorAll('tunepad-file');
        // for (const f of files) {
        //     const file = f as TunePadFile;
        //     data.files.push(await file.save());
        // }

        document.querySelectorAll('tunepad-cell').forEach(el => {
            const cell = el as TunePadCell;
            data.cells.push(cell.save());
        });
        return data;
    }



    public async restore(data : any) {
        Object.entries(data).forEach(([key, value]) => {
            if (!['cells', 'files', 'persistence', 'awareness'].includes(key)) {
                this.setAttribute(key, value as string);
            }
        });

        // FIXME: Temporarily disabling file saving because it wastes a ton of space in the database
        // if (Array.isArray(data.files)) {
        //     for (const f of data.files) {
        //         const file = this.querySelector(`tunepad-file[uuid="${f.uuid}"]`);
        //         if (file) (file as TunePadFile).restore(f);
        //     }
        // }
        if (Array.isArray(data.cells)) {
            for (const o of data.cells) {
                let cell = this.querySelector(`tunepad-cell[uuid="${o.uuid}"]`);
                if (cell) {
                    (cell as TunePadCell).restore(o);
                } else {
                    cell = document.createElement('tunepad-cell');
                    this.querySelector('tunepad-cell-list')?.append(cell);
                    (cell as TunePadCell).restore(o);
                }
            }
        }
    }


/**
 * Move a target <tunepad-cell> element to a new location.
 * Have to create a clone of the original to do this correctly.
 * 
 * @param moved the uuid of the cell to move
 * @param newPosition index of the cell's new position
 * @returns the <tunepad-cell> that was reinserted
 */
    public reorderCells(moved : string, newPosition : number) : TunePadCell | undefined {
        const parent = this.querySelector('tunepad-cell-list');
        if (!parent || newPosition < 0) return undefined;

        function cellAtIndex(index : number) : TunePadCell | null {
            const cells = parent!.querySelectorAll('tunepad-cell');
            if (index >= 0 && index < cells.length) {
                return cells[index] as TunePadCell;
            } else {
                return null;
            }
        }

        const cell = parent!.querySelector(`tunepad-cell[uuid="${moved}"]`) as TunePadCell | undefined;
        if (cell) {
            cell.pauseAudio();
            const clone = document.createElement('tunepad-cell') as TunePadCell;
            clone.setAttribute('uuid', cell.uuid);
            cell?.getAttributeNames().forEach(attrib => {
                clone.setAttribute(attrib, `${cell.getAttribute(attrib)}`);
            });
            clone.replaceCode(cell.code);
            cell.remove();
            const after = cellAtIndex(newPosition);
            parent.insertBefore(clone, after);
            this.waitForElementConnected(clone).then(ready => {
                clone.recompile(true);
            });
            return clone;
        }
    }


    public async recompileAll() {
        const cells = document.querySelectorAll('tunepad-cell');
        for (const cell of cells) {
            await PythonRuntime.preload((cell as TunePadCell));
        }
        for (const cell of cells) {
            await (cell as TunePadCell).recompile(true);
        }
    }


    private async waitForWindowLoad() : Promise<void> {
        return new Promise((resolve) => {
            if (document.readyState === 'complete') {
                resolve();
            } else {
                window.addEventListener('load', () => {
                    resolve();
                });
            }
        });
    }


    private setReadOnly(ro : boolean) {
        this.querySelectorAll('tunepad-cell')?.forEach(cell => {
            cell.setAttribute('readonly', `${ro}`);
        });
        this.querySelector('tunepad-project-menu')?.setAttribute('readonly', `${ro}`);
    }


    private emitUpdateEvent(property : string, value : any) {
        const uuid = this.uuid;
        this.dispatchEvent(new CustomEvent("update-project", {
            bubbles: false,
            composed: true,
            detail: { uuid, property, value }
        }));
    }

    private relayEvent(e : CustomEvent) {
        this.dispatchEvent(new CustomEvent(e.type, {
            bubbles: false,
            composed: true,
            detail: (e as CustomEvent).detail 
        }));
    }


    private waitForElementConnected(element : Element) : Promise<boolean> {
        return new Promise(resolve => {
            function checkConnection() {
                if (element.isConnected) {
                    resolve(true);
                } else {
                    requestAnimationFrame(checkConnection);
                }
            }
            requestAnimationFrame(checkConnection);
        });
    }
}

