import html from './time-dialog.module.html';
import { toInt } from '../../audio';

/**
 * Time Signature Dialog (extends HTMLDialogElement)
 * ```html
 * <dialog is="time-signature-dialog" time="4/4"></dialog>
 * ```
 */

export class TimeSignatureDialog extends HTMLDialogElement {

    static readonly ELEMENT = "time-signature-dialog";

    static observedAttributes = [ ];


    static show(numerator : number, denominator : number) : HTMLDialogElement {
        const dialog = document.createElement('dialog', { is: TimeSignatureDialog.ELEMENT}) as TimeSignatureDialog;
        dialog.setTimeSignature(numerator, denominator);
        dialog.classList.add('time-signature-dialog');
        document.body.append(dialog);
        dialog.showModal();
        dialog.addEventListener('click', (event) => {
            const r = dialog.getBoundingClientRect();
            const cx = event.clientX;
            const cy = event.clientY;
            if (cy < r.top || cy > r.bottom || cx < r.left || cx > r.right) {
                dialog.close();
                dialog.remove();
            }
        });
        return dialog;
    }


    constructor() {
        super();
        this.innerHTML = html;
    }

    connectedCallback() {
        const numField = this.querySelector('.numerator') as HTMLInputElement;
        const denField = this.querySelector('.denominator') as HTMLInputElement;
        numField?.addEventListener('keypress', e => { if (e.key === 'Enter') { numField.blur(); }});
        denField?.addEventListener('keypress', e => { if (e.key === 'Enter') { denField.blur(); }})
        numField?.addEventListener('input', e => {
            numField.value = numField.value.replaceAll(/[^0-9]/g, '');
        });
        denField?.addEventListener('input', e => {
            denField.value = denField.value.replaceAll(/[^0-9]/g, '');
        });
        numField?.addEventListener('blur', e => {
            this.setTimeSignature(this.getNumerator(), this.getDenominator());
            this.emitUpdateEvent();

        });
        denField?.addEventListener('blur', e => {
            this.setTimeSignature(this.getNumerator(), this.getDenominator());
            this.emitUpdateEvent();
        });
    }

    disconnectedCallback() { }

    /**
     * When an attribute is changed on our custom component, this gets fired...
     */
    attributeChangedCallback(name : string, oldValue : string, newValue : string) { }


    private setTimeSignature(numer : number, denom : number) {
        numer = Math.max(1, Math.min(32, numer));
        denom = [1, 2, 4, 8, 16, 32, 64].includes(denom) ? denom : 4;
        (this.querySelector('.numerator') as HTMLInputElement).value = `${numer}`;
        (this.querySelector('.denominator') as HTMLInputElement).value = `${denom}`;
    }

    private getNumerator() : number {
        return toInt((this.querySelector('.numerator') as HTMLInputElement).value, 4);
    }

    private getDenominator() : number {
        return toInt((this.querySelector('.denominator') as HTMLInputElement).value, 4);
    }

    /**
     * Fire custom events whenever the value is changed by the user
     */
    private emitUpdateEvent() {
        const numerator = this.getNumerator();
        const denominator = this.getDenominator();
        this.dispatchEvent(
            new CustomEvent('time-signature', {
                bubbles: true,
                composed: true,
                detail: { numerator, denominator }
            })
        );
    }
}
