import html from './share-dialog.module.html';
import { Creator, Renderer } from 'easy-qrcode';


const ValidShareOptions = ['private', 'viewonly', 'collaborative'] as const;
export type ShareOption = typeof ValidShareOptions[number];


/**
 * Project sharing options
 * ```html
 * <dialog is="share-dialog" mode="private" share-link="https://..."></dialog>
 * ```
 */
export class ShareDialog extends HTMLDialogElement {

    static readonly ELEMENT = "share-dialog";

    static observedAttributes = [
        'share-link',
        'mode'  // private, viewonly, collaborative
    ];


    constructor() {
        super();
        this.innerHTML = html;
        this.classList.add('share-dialog');
    }

    connectedCallback() {
        const input = this.querySelector('#share-url') as HTMLInputElement;
        input.addEventListener('focus', e => {
            input.select();
        });
        this.querySelector('#copy-button')?.addEventListener('click', e => {
            navigator.clipboard.writeText(input.value);
            input.select();
        });
        this.querySelectorAll('input[type="radio"]').forEach(radio => {
            radio.addEventListener('change', e => {
                const value = (radio as HTMLInputElement).value;
                this.setAttribute('mode', value)
                this.dispatchEvent(new CustomEvent('share-update', { 
                    bubbles: false, composed: true, detail : { share : value }
                }));
            });
        });
        this.addEventListener('click', (event) => {
            const r = this.getBoundingClientRect();
            const cx = event.clientX;
            const cy = event.clientY;
            if (cy < r.top || cy > r.bottom || cx < r.left || cx > r.right) {
                this.close();
                this.remove();
            }
        });
        this.querySelector('#close-button')?.addEventListener('click', e => {
            this.close();
            this.remove();
        });
    }

    disconnectedCallback() { }

    /**
     * When an attribute is changed on our custom component, this gets fired...
     */
    attributeChangedCallback(name : string, oldValue : string, newValue : string) {
        if (name === 'share-link' && newValue && newValue !== oldValue) {
            this.generateQRCode(newValue);
            const input = this.querySelector('#share-url') as HTMLInputElement;
            input.value = newValue;
        }
        else if (name === 'mode') {
            const opt = this.querySelector(`#option-${newValue}`);
            if (opt) { (opt as HTMLInputElement).checked = true }
        }
    }


    private generateQRCode(url : string) {
        const qrCreator = new Creator();
        const qrRenderer = new Renderer();
        const canvas = this.querySelector('canvas#qrcode');
        qrCreator.add(url);
        qrCreator.create();
        const matrix = qrCreator.getMatrix();
        qrRenderer.drawCanvas(matrix, canvas as HTMLCanvasElement);
    }
}
