import html from './key-dialog.module.html';

/**
 * Key Dialog (extends HTMLDialogElement)
 *
 * ```javascript
 * KeyDialog.show('C major');
 * ```
 */

export class KeyDialog extends HTMLDialogElement {

    static readonly ELEMENT = "key-dialog";

    static observedAttributes = [ 'key' ];


    static show(key : string) : HTMLDialogElement {
        const dialog = document.createElement('dialog', { is: KeyDialog.ELEMENT}) as HTMLDialogElement;
        dialog.classList.add('key-dialog');
        dialog.setAttribute('key', key);
        document.body.append(dialog);
        dialog.showModal();
        dialog.addEventListener('click', (event) => {
            const r = dialog.getBoundingClientRect();
            const cx = event.clientX;
            const cy = event.clientY;
            if (cy < r.top || cy > r.bottom || cx < r.left || cx > r.right) {
                dialog.close();
                dialog.remove();
            }
        });
        return dialog;
    }


    constructor() {
        super();
        this.innerHTML = html;
    }

    connectedCallback() {
        this.querySelector('circle-of-fifths')?.addEventListener('selected', e => {
            this.emitUpdateEvent('key', (e as CustomEvent).detail.value);
            this.close();
            this.remove();
        });
    }

    disconnectedCallback() { }

    /**
     * When an attribute is changed on our custom component, this gets fired...
     */
    attributeChangedCallback(name : string, oldValue : string, newValue : string) {
        this.querySelector('circle-of-fifths')?.setAttribute('selected', newValue);
    }

    /**
     * Fire custom events whenever the value is changed by the user
     */
    private emitUpdateEvent(name : string, value : number) {
        this.dispatchEvent(
            new CustomEvent(name, {
                bubbles: true,
                composed: true,
                detail: { value }
            })
        );
    }
}
