import { TunePadCell } from './cell';
import { TunePadProject } from './project';
import * as Y from 'yjs'
import { WebsocketProvider } from 'y-websocket'
import { yCollab } from 'y-codemirror.next'

/**
 * Persistence provider using Y.js web socket provider
 */
export class ProjectPersistence {

    private provider : WebsocketProvider;
    private yProject : Y.Map<string>;
    private yCells : Y.Map<Y.Text>;
    private project : TunePadProject;

    private static instance : ProjectPersistence | undefined;


    /**
     * Using a singleton pattern to avoid creating multiple yDocs.
     * This gets called from TunePadProject.
     */
    public static Initialize(project : TunePadProject) {
        ProjectPersistence.instance = ProjectPersistence.instance ?? new ProjectPersistence(project);
    }


    /**
     * Set up the yDoc and websocket provider. Then wait for sync...
     */
    private constructor(project : TunePadProject) {
        this.project = project;

        // create main Y.Doc and project Y.Map
        const yDoc = new Y.Doc();
        this.yProject = yDoc.getMap('project');
        this.yCells = yDoc.getMap('cells');


        // connect to the persistence provider
        const wss = project.getAttribute('persistence') as string;
        this.provider = new WebsocketProvider(wss, project.uuid, yDoc)
        //wsProvider.on('status', event => { console.log(event.status) });


        // set awareness
        this.setAwareness();

        // wait for the provider to sync
        this.provider.on('sync', async ok => { if (ok) this.init() });
    }


    /**
     * This gets called after the provider has synced up with the datastore.
     */
    private init() {

    
        // set initial project data from yjs
        this.yLoad();


        // listen for local project changes
        this.project.addEventListener('update-project', e => this.ySave());
        this.project.addEventListener('update-cell', e => this.ySave());
        this.project.addEventListener('delete-cell', e => this.ySave());
        this.project.addEventListener('add-cell', e => this.addCell('piano'));
        this.project.addEventListener('copy-cell', e => this.copyCell((e as CustomEvent).detail.uuid));
        this.project.addEventListener('cell-added', e => { });
        this.project.addEventListener('cell-removed', e => { });
        this.project.addEventListener('reorder-cells', e => {
            const detail = (e as CustomEvent).detail;
            const cell = this.project.reorderCells(detail.moved, detail.newPosition);
            if (cell) this.bindYText(cell);
            this.ySave();
        });


        // bind yText to codemirror for each cell
        document.querySelectorAll('tunepad-cell').forEach(cell => this.bindYText(cell as TunePadCell));

    
        // listen for remote changes to project data
        this.yProject.observe(evt => {
            evt.changes.keys.forEach((change, key) => {
                if (change.action === 'add' || change.action === 'update') {
                    this.yLoad();
                } else if (change.action === 'delete') {
                    console.log('delete project??')
                }
            });

            // update last saved info
            document.querySelectorAll('.last-saved').forEach(el => { 
                el.innerHTML = `Last Saved: ${this.formatDate()}`
            });
        });


        // initial compile of all of the cells
        this.waitForElementConnected(this.project).then(ready => {
            this.project.recompileAll();
        });
    }


    private ySave() {
        this.yProject.set('data', JSON.stringify(this.project.save()));
    }


    private yLoad() {
        if (this.yProject.has('data')) {
            const data = JSON.parse(this.yProject.get('data') as string);
            this.restore(data);
        }
    }


    /**
     * From <tunepad-project awareness="username:usercolor">
     */
    private setAwareness() {
        let username = this.project.getAttribute('awareness') || 'Anonymous';
        let usercolor = 'rgb(160, 120, 200)';

        if (username.includes(':')) {
            usercolor = username.split(':')[1];
            username = username.split(':')[0];
        }

        this.provider.awareness.setLocalStateField('user', {
            name: username,
            color: usercolor,
            colorLight: usercolor
        });
    }


    /**
     * When the add cell button is pressed
     */
    private async addCell(instrument : string = 'piano') : Promise<TunePadCell> {
        const attribs : any = { };
        //if (instrument === 'piano' || instrument === 'keys') {
            attribs.name = 'new piano';
            attribs.theme = 'bitcrush';
            attribs.patch = 'grand-piano';
            attribs.autocompile = 'true';
            attribs.instrument = 'piano';
            attribs.class = 'tutorial music';
            attribs.timeline = 'midi';
        //}

        // create the new <tunepad-cell> and set attributes
        const cell = document.createElement('tunepad-cell') as TunePadCell;
        Object.entries(attribs).forEach(([key, value]) => {
            cell.setAttribute(key, value as string);
        });
        cell.setAttribute('uuid', cell.uuid);

        // add the cell to the cell list
        document.querySelector('tunepad-cell-list')?.append(cell);

        // after bind events and ytext
        const initialText = '# add code here...\n\n\n\n\n\n\n\n\n\n';
        cell.replaceCode(initialText);
        this.bindYText(cell, initialText);

        // recompile after loading
        await this.waitForElementConnected(cell);
        cell.recompile(true);
        this.ySave();

        return cell;
    }


    private async copyCell(uuid : string) : Promise<TunePadCell> {
        // create the new <tunepad-cell> and copy the attributes over
        const original = document.querySelector(`tunepad-cell[uuid="${uuid}"]`) as TunePadCell;
        const cell = document.createElement('tunepad-cell') as TunePadCell;
        original.getAttributeNames().forEach(attrib => {
            if (attrib !== 'uuid') {
                cell.setAttribute(attrib, `${original.getAttribute(attrib)}`);
            }
        });
        cell.setAttribute('uuid', cell.uuid);

        // add the cell to the cell list
        document.querySelector('tunepad-cell-list')?.append(cell);

        // after bind events and ytext
        const code = original.code;
        cell.replaceCode(code);
        this.bindYText(cell, code);

        // recompile after loading
        await this.waitForElementConnected(cell);
        cell.recompile(true);
        this.ySave();
        return cell;
    }


    private bindYText(cell : TunePadCell, initialText : string | undefined = undefined) {
        const uuid = cell.getAttribute('uuid') as string;
        const editor = cell.getEditor();
        const existing = this.yCells.has(uuid);
        const code = (editor as any).code;
        const ytext = existing ? this.yCells.get(uuid)! : new Y.Text();
        if (!existing) {
            ytext.insert(0, initialText ?? code);
            this.yCells.set(uuid, ytext);
        } else {
            cell.replaceCode(ytext.toString());
        }
        const undoManager = new Y.UndoManager(ytext);
        const extensions = yCollab(ytext, this.provider.awareness, { undoManager });
        this.waitForElementConnected(editor).then(ready => {
            editor.bindCollaboration([ extensions ]);
        });
    }


    private formatDate(date : number = -1) {
        if (date < 0) date = Date.now();
        if (typeof date === 'string') date = Date.parse(date);
        return this.date_formatter.format(date);
    }
    private date_formatter = new Intl.DateTimeFormat('en-US', {
        month: 'long', day: 'numeric',  hour: '2-digit', minute: '2-digit'
    });


    private restore(data : any) {
        Object.entries(data).forEach(([key, value]) => {
            if (key !== 'cells' && key !== 'files') {
                this.project.setAttribute(key, value as string);
            }
        });

        const cell_ids : string[] = [];

        if (Array.isArray(data.cells)) {
            for (const o of data.cells) {
                const uuid = o['uuid'];
                if (uuid) {
                    cell_ids.push(uuid);
                    let cell = document.querySelector(`tunepad-cell[uuid="${uuid}"]`);
                    if (cell) {
                        (cell as TunePadCell).restore(o, false);
                    } else {
                        cell = document.createElement('tunepad-cell');
                        document.querySelector('tunepad-cell-list')?.append(cell);
                        (cell as TunePadCell).restore(o, false);
                        this.bindYText(cell as TunePadCell);
                        this.waitForElementConnected(cell).then(ready => {
                            (cell as TunePadCell).recompile(true);
                        });
                    }
                }
            }
        }

        // delete cells that are no longer in yjs
        document.querySelectorAll('tunepad-cell').forEach(cell => {
            const uuid = cell.getAttribute('uuid') ?? '';
            if (!cell_ids.includes(uuid)) cell.remove();
        });


        // do we need a reorder?
        while (this.reorder(cell_ids)) {
            ; //console.log('reordering');
        }
    }


    // compare the current <tunepad-cell> element ordering to the data object ordering
    private reorder(ordering : string[]) : boolean {
        const cells = document.querySelectorAll('tunepad-cell');

        // this should never happen, but just in case
        if (cells.length !== ordering.length) return false;

        for (let i=0; i < (cells.length - 1); i++) {
            const uuid = `${cells[i].getAttribute('uuid')}`;

            // we have a mismatch? which means either this cell moved down or another cell moved up
            let newCell = undefined;
            if (uuid !== ordering[i]) {
                if (uuid === ordering[i+1]) {
                    newCell = this.project.reorderCells(ordering[i], i); // another moved up
                } else {
                    newCell = this.project.reorderCells(uuid, ordering.indexOf(uuid)); // this moved down
                }
                if (newCell) {
                    this.bindYText(newCell);
                }
                return true; // indicate that there was at least one reordering
            }
        }
        return false;
    }


    private waitForElementConnected(element : Element) : Promise<boolean> {
        return new Promise(resolve => {
            function checkConnection() {
                if (element.isConnected) {
                    resolve(true);
                } else {
                    requestAnimationFrame(checkConnection);
                }
            }
            requestAnimationFrame(checkConnection);
        });
    }
}

